import { CLI_COMMAND_NAME as CLI } from "../distribution.js";
import { EXIT_CODES } from "./errors.js";
const GROUP_TITLES = {
    develop: "Develop",
    deploy: "Deploy and operate",
    account: "Account",
    other: "Other",
};
const GROUP_ORDER = ["develop", "deploy", "account", "other"];
function visible(commands) {
    return commands.filter((spec) => spec.hidden !== true);
}
function usageLine(spec) {
    const args = (spec.args ?? []).map((arg) => {
        const text = `<${arg.name}>${arg.variadic === true ? "..." : ""}`;
        return arg.required === true ? text : `[${text}]`;
    });
    const hasFlags = Object.values(spec.flags).some((flag) => flag.hidden !== true);
    return [`${CLI} ${spec.name}`, ...args, ...(hasFlags ? ["[flags]"] : [])].join(" ");
}
function flagLabel(name, flag) {
    const short = flag.short === undefined ? "" : `-${flag.short}, `;
    const value = flag.type === "string" ? ` ${flag.value ?? "<value>"}` : "";
    return `${short}--${name}${value}`;
}
function flagDetail(flag) {
    const notes = [];
    if (flag.choices !== undefined) {
        notes.push(`one of: ${flag.choices.join(", ")}`);
    }
    if (flag.multiple === true) {
        notes.push("repeatable");
    }
    if (flag.default !== undefined && flag.default !== false) {
        notes.push(`default: ${String(flag.default)}`);
    }
    return notes.length === 0 ? flag.description : `${flag.description} (${notes.join("; ")})`;
}
function table(rows, width = Math.min(30, Math.max(...rows.map(([left]) => left.length))), indent = "  ") {
    return rows
        .map(([left, right]) => left.length > width
        ? `${indent}${left}\n${indent}${" ".repeat(width + 2)}${right}`
        : `${indent}${left.padEnd(width + 2)}${right}`)
        .join("\n");
}
/** Help for one command, as printed by `agent-sdk <command> --help`. */
const EFFECT_NOTES = {
    read: undefined,
    write: "Changes state. --dry-run shows what it would do and changes nothing.",
    destructive: "Cannot be undone. Asks you to type a confirm word; --yes skips the question (needed without a TTY). --dry-run shows what it would do.",
    interactive: "Runs until you stop it.",
};
export function commandHelp(spec) {
    const sections = [`Usage: ${usageLine(spec)}`, "", spec.summary];
    const effectNote = EFFECT_NOTES[spec.effect];
    if (effectNote !== undefined) {
        sections.push(effectNote);
    }
    if (spec.description !== undefined) {
        sections.push("", spec.description.trim());
    }
    if (spec.args !== undefined && spec.args.length > 0) {
        sections.push("", "Arguments:", table(spec.args.map((arg) => [arg.name, arg.description])));
    }
    const flags = Object.entries(spec.flags).filter(([, flag]) => flag.hidden !== true);
    if (flags.length > 0) {
        sections.push("", "Flags:", table(flags.map(([name, flag]) => [flagLabel(name, flag), flagDetail(flag)])));
    }
    if (spec.examples !== undefined && spec.examples.length > 0) {
        sections.push("", "Examples:", ...spec.examples.map((example) => `  ${example}`));
    }
    return `${sections.join("\n")}\n`;
}
function childrenOf(commands, word) {
    return visible(commands).filter((spec) => spec.name.startsWith(`${word} `));
}
function parentSummary(children) {
    return children.find((spec) => spec.parentSummary !== undefined)?.parentSummary;
}
/** Subcommands of one parent word, as printed by `agent-sdk secrets` alone. */
export function groupHelp(commands, word) {
    const children = childrenOf(commands, word);
    if (children.length === 0) {
        return undefined;
    }
    const lines = [`Usage: ${CLI} ${word} <subcommand> [flags]`];
    const summary = parentSummary(children);
    if (summary !== undefined) {
        lines.push("", summary);
    }
    lines.push("", "Subcommands:", table(children.map((spec) => [spec.name, spec.summary])), "", `Run \`${CLI} ${word} <subcommand> --help\` for one subcommand.`, "");
    return lines.join("\n");
}
/**
 * One index row per top-level word: `deploy`, `eval [status|cancel]` for a
 * command with subcommands, or `secrets <set|list|unset>` for a parent.
 */
function indexRows(commands, group) {
    const rows = [];
    const seen = new Set();
    for (const spec of visible(commands)) {
        const word = spec.name.split(" ")[0] ?? spec.name;
        if (seen.has(word)) {
            continue;
        }
        seen.add(word);
        if (spec.group !== group) {
            continue;
        }
        const self = visible(commands).find((candidate) => candidate.name === word);
        const children = childrenOf(commands, word);
        const subs = children.map((child) => child.name.slice(word.length + 1)).join("|");
        if (self !== undefined) {
            rows.push([children.length === 0 ? word : `${word} [${subs}]`, self.summary]);
            continue;
        }
        rows.push([`${word} <${subs}>`, parentSummary(children) ?? children[0]?.summary ?? ""]);
    }
    return rows;
}
/** Short command index, as printed by bare `agent-sdk`. */
export function indexHelp(commands) {
    const sections = [
        `${CLI} — build, test, and deploy Cursor agents`,
        "",
        `Usage: ${CLI} <command> [flags]`,
    ];
    const groups = GROUP_ORDER.map((group) => ({ group, rows: indexRows(commands, group) }));
    // One column width for every group, so the index reads as one table.
    const width = Math.min(30, Math.max(...groups.flatMap(({ rows }) => rows.map(([left]) => left.length))));
    for (const { group, rows } of groups) {
        if (rows.length > 0) {
            sections.push("", `${GROUP_TITLES[group]}:`, table(rows, width));
        }
    }
    sections.push("", "Output is text. Pass --json for one JSON document on stdout, errors included.", "", "Exit codes:", table(EXIT_CODES.map(({ exitCode, meaning }) => [String(exitCode), meaning])), "", `Run \`${CLI} <command> --help\` for one command, \`${CLI} help --all\` for every command,`, `or \`${CLI} help <command> --json\` for one command as JSON.`);
    return `${sections.join("\n")}\n`;
}
/** The index plus every command's help, as printed by `agent-sdk help --all`. */
export function referenceHelp(commands) {
    return [indexHelp(commands), ...visible(commands).map((spec) => commandHelp(spec))].join("\n");
}
/**
 * The index plus `serve`'s help, as printed by `agent-sdk --help` and `agent-sdk help`.
 * Cursor hosting runs `agent-sdk --help` and looks for `serve` flags such as
 * `--cloud-tools-url` before it passes them, so `serve`'s flags stay here.
 */
export function rootHelp(commands) {
    const serve = commands.find((spec) => spec.name === "serve");
    return serve === undefined
        ? indexHelp(commands)
        : `${indexHelp(commands)}\n${commandHelp(serve)}`;
}
/** Names and summaries only, for `agent-sdk help --json`. */
export function helpIndexJson(commands, version) {
    return {
        name: CLI,
        version,
        exitCodes: EXIT_CODES,
        commands: visible(commands).map((spec) => ({
            name: spec.name,
            group: spec.group,
            summary: spec.summary,
            effect: spec.effect,
        })),
    };
}
/** The command table as data, for `agent-sdk help --json`. */
export function helpJson(commands, version) {
    return {
        name: CLI,
        version,
        exitCodes: EXIT_CODES,
        commands: visible(commands).map((spec) => ({
            name: spec.name,
            group: spec.group,
            summary: spec.summary,
            description: spec.description?.trim(),
            effect: spec.effect,
            args: (spec.args ?? []).map((arg) => ({
                name: arg.name,
                description: arg.description,
                required: arg.required === true,
                variadic: arg.variadic === true,
                kind: arg.kind,
            })),
            flags: Object.entries(spec.flags)
                .filter(([, flag]) => flag.hidden !== true)
                .map(([name, flag]) => ({
                name,
                type: flag.type,
                short: flag.short,
                multiple: flag.multiple === true,
                default: flag.default,
                choices: flag.choices,
                integer: flag.integer,
                kind: flag.kind,
                description: flag.description,
            })),
            examples: spec.examples ?? [],
        })),
    };
}
